package projectaccess

import (
 "context"
 "errors"
 "os"
 "path/filepath"
 "reflect"
 "testing"

 "github.com/qingwo1991-debug/ai-novel-writer-web/backend-go/internal/knowledgecopy"
 "github.com/qingwo1991-debug/ai-novel-writer-web/backend-go/internal/projectfs"
)
func knowledgeAccessFixture(t *testing.T)Config{t.Helper();c:=accessFixture(t);c.Knowledge=&KnowledgeConfig{Copy:projectfs.KnowledgeBudget{MaxBytes:16*1024*1024,MaxEntries:100,MaxDepth:16},Metadata:knowledgecopy.Budget{MaxMetadataBytes:1024*1024,MaxCopies:100}};storage:=filepath.Join(c.ProjectPath,".ai-novel");for _,name:=range []string{"lancedb/chunks.lance/_versions","knowledge-copies"}{if err:=os.MkdirAll(filepath.Join(storage,name),0700);err!=nil{t.Fatal(err)}};writeAccess(t,filepath.Join(storage,"lancedb/chunks.lance/_versions/1.manifest"),[]byte("opaque synthetic Lance bytes, no native reader in metadata preflight"));writeAccess(t,filepath.Join(storage,"embedding-spaces.json"),[]byte("\n{\"version\":1,\"activeGeneration\":null,\"spaces\":[]}\n"));writeAccess(t,filepath.Join(storage,"vectors.json.migrated"),[]byte("opaque historical receipt"));writeAccess(t,filepath.Join(storage,"knowledge-copies", "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.json"),[]byte(`{"content":"unindexed synthetic author edit","indexedHash":"old","edited":true,"indexDirty":true}`));return c}
func TestPreflightKnowledgePhysicalAndMetadataEvidence(t *testing.T){c:=knowledgeAccessFixture(t);before:=sourceBytes(t,c);for range 2{report,err:=Preflight(context.Background(),c);if err!=nil{t.Fatal(err)};if report.Knowledge==nil||!report.Knowledge.Physical.LanceDB||!report.Knowledge.Physical.KnowledgeCopies||report.Knowledge.Physical.Digest==""||report.Knowledge.Metadata.Copies!=1||report.Knowledge.Metadata.Dirty!=1||report.Knowledge.Metadata.Edited!=1{t.Fatal("incomplete copy evidence",report)};accessClean(t,c)};if !reflect.DeepEqual(before,sourceBytes(t,c)){t.Fatal("source SQLite changed")}}
func TestPreflightKnowledgeAbsentDoesNotCreateLance(t *testing.T){c:=accessFixture(t);c.Knowledge=&KnowledgeConfig{Copy:projectfs.KnowledgeBudget{MaxBytes:1024,MaxEntries:100,MaxDepth:8},Metadata:knowledgecopy.Budget{MaxMetadataBytes:1024,MaxCopies:10}};report,err:=Preflight(context.Background(),c);if err!=nil||report.Knowledge==nil||report.Knowledge.Physical.LanceDB{t.Fatal(report,err)};if _,err:=os.Lstat(filepath.Join(c.ProjectPath,".ai-novel/lancedb"));!errors.Is(err,os.ErrNotExist){t.Fatal("created original Lance",err)};accessClean(t,c)}
func TestPreflightKnowledgeDriftAndRefusalZeroReport(t *testing.T){for _,kind:=range []string{"source-content","source-new-file","source-replace-inode","late-legacy","copy-content","metadata-invalid","bytes-budget","entries-budget","cancel"}{t.Run(kind,func(t *testing.T){c:=knowledgeAccessFixture(t);ctx,cancel:=context.WithCancel(context.Background());defer cancel();storage:=filepath.Join(c.ProjectPath,".ai-novel");if kind=="metadata-invalid"{writeAccess(t,filepath.Join(storage,"embedding-spaces.json"),[]byte(`{"version":2,"spaces":[]}`))};if kind=="bytes-budget"{c.Knowledge.Copy.MaxBytes=1};if kind=="entries-budget"{c.Knowledge.Copy.MaxEntries=1};hook:=func(*projectfs.Project)error{file:=filepath.Join(storage,"lancedb/chunks.lance/_versions/1.manifest");switch kind{case "source-content":return os.WriteFile(file,[]byte("changed"),0600);case "source-new-file":return os.WriteFile(filepath.Join(storage,"knowledge-copies/late"),[]byte("new"),0600);case "source-replace-inode":data,err:=os.ReadFile(file);if err!=nil{return err};if err:=os.Remove(file);err!=nil{return err};return os.WriteFile(file,data,0600);case "late-legacy":return os.WriteFile(filepath.Join(storage,"vectors.json"),[]byte("pending"),0600);case "copy-content":entries,err:=os.ReadDir(c.ScratchParent);if err!=nil{return err};return os.WriteFile(filepath.Join(c.ScratchParent,entries[0].Name(),"knowledge/lancedb/chunks.lance/_versions/1.manifest"),[]byte("changed copy"),0600);case "cancel":cancel()};return nil};report,err:=preflight(ctx,c,hook);if err==nil||!reflect.DeepEqual(report,Report{}){t.Fatal("failure published evidence",report,err)};if kind=="cancel"&&!errors.Is(err,context.Canceled){t.Fatal(err)};accessClean(t,c)})}}
func TestPreflightKnowledgePendingLegacyRejected(t *testing.T){for _,name:=range []string{"vectors.json","vectors.json.migration-journal.json"}{t.Run(name,func(t *testing.T){c:=knowledgeAccessFixture(t);writeAccess(t,filepath.Join(c.ProjectPath,".ai-novel",name),[]byte("never parsed"));report,err:=Preflight(context.Background(),c);if err==nil||!reflect.DeepEqual(report,Report{}){t.Fatal(report,err)};accessClean(t,c)})}}
func TestPreflightKnowledgeRenamedScratchCleansPinnedAssets(t *testing.T){c:=knowledgeAccessFixture(t);moved:="";report,err:=preflight(context.Background(),c,func(*projectfs.Project)error{entries,err:=os.ReadDir(c.ScratchParent);if err!=nil{return err};original:=filepath.Join(c.ScratchParent,entries[0].Name());moved=original+"-moved";if err:=os.Rename(original,moved);err!=nil{return err};if err:=os.Mkdir(original,0700);err!=nil{return err};return os.WriteFile(filepath.Join(original,"keep"),[]byte("unknown replacement"),0600)});if !errors.Is(err,ErrCleanup)||!reflect.DeepEqual(report,Report{}){t.Fatal(report,err)};entries,err:=os.ReadDir(moved);if err!=nil||len(entries)!=0{t.Fatal("copied assets leaked after rename",entries,err)}}
